const { Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell, WidthType, HeadingLevel, Header, AlignmentType } = require('docx');
const fs = require('fs');

// Helper to create a table cell with specified width percentage and text
function makeCell(text, widthPct, bold = false) {
  return new TableCell({
    width: { size: widthPct, type: WidthType.PERCENTAGE },
    children: [new Paragraph({ children: [new TextRun({ text, bold })] })],
  });
}

// Page 1: Chinese
const page1Children = [
  new Paragraph({ text: '项目简报', heading: HeadingLevel.HEADING_1 }),
  new Paragraph({ children: [new TextRun({ text: '项目名称：合成项目晨星', bold: true })] }),
  new Paragraph({ children: [new TextRun('目标：测试文档')] }),
  new Paragraph({ spacing: { before: 200 }, children: [new TextRun({ text: '里程碑', bold: true, size: 24 })] }),
  new Table({
    width: { size: 100, type: WidthType.PERCENTAGE },
    columnWidths: [5000, 5000],
    rows: [
      new TableRow({ children: [makeCell('里程碑', 50, true), makeCell('说明', 50, true)] }),
      new TableRow({ children: [makeCell('需求确认', 50), makeCell('确认项目需求与范围', 50)] }),
      new TableRow({ children: [makeCell('原型验证', 50), makeCell('完成原型并进行验证', 50)] }),
    ],
  }),
  new Paragraph({ spacing: { before: 300 }, children: [new TextRun({ text: '预算说明', bold: true, size: 24 })] }),
  new Paragraph({ children: [new TextRun('本项目预算当前状态为"未知"。未获拨款、尚未批准或费用决策暂停等表述均不适用，亦无任何具体数字可供引用。请以后续正式通知为准。')] }),
];

// Page 2: English
const page2Children = [
  new Paragraph({ text: 'Project Brief', heading: HeadingLevel.HEADING_1 }),
  new Paragraph({ children: [new TextRun({ text: 'Project Name: Synthetic Project Morning Star', bold: true })] }),
  new Paragraph({ children: [new TextRun('Objective: Document testing')] }),
  new Paragraph({ spacing: { before: 200 }, children: [new TextRun({ text: 'Milestones', bold: true, size: 24 })] }),
  new Table({
    width: { size: 100, type: WidthType.PERCENTAGE },
    columnWidths: [5000, 5000],
    rows: [
      new TableRow({ children: [makeCell('Milestone', 50, true), makeCell('Description', 50, true)] }),
      new TableRow({ children: [makeCell('Confirm Requirements', 50), makeCell('Confirm project requirements and scope', 50)] }),
      new TableRow({ children: [makeCell('Validate Prototype', 50), makeCell('Complete prototype and validate', 50)] }),
    ],
  }),
  new Paragraph({ spacing: { before: 300 }, children: [new TextRun({ text: 'Budget Note', bold: true, size: 24 })] }),
  new Paragraph({ children: [new TextRun('The budget for this project is currently "unknown". No specific figures are available. Statements such as unfunded, not yet approved, or cost decision on hold do not apply. Please refer to subsequent official communication.')] }),
];

const headerParagraph = new Paragraph({
  alignment: AlignmentType.CENTER,
  children: [new TextRun({ text: '晨星测试', bold: true, size: 18 })],
});

const doc = new Document({
  sections: [
    {
      headers: { default: new Header({ children: [headerParagraph] }) },
      children: page1Children,
    },
    {
      headers: { default: new Header({ children: [headerParagraph] }) },
      children: page2Children,
    },
  ],
});

const outDir = process.env.SKILL_SANDBOX_OUT_DIR || '/workspace';
Packer.toBuffer(doc).then((buf) => {
  const outPath = outDir + '/report.docx';
  fs.writeFileSync(outPath, buf);
  console.log('Written:', outPath);
});

